SELECT c.id, c.product_id AS productId, c.code, c.code_type AS codeType, c.batch_no AS batchNo, c.qr_image_url AS qrImageUrl, c.scan_limit AS scanLimit, c.scan_count AS scanCount, c.void_scan_count AS voidScanCount, c.over_limit_scan_count AS overLimitScanCount, c.first_scan_time AS firstScanTime, c.last_scan_time AS lastScanTime, c.status, c.create_time AS createTime, p.product_no AS productNo, p.product_name AS productName, p.category, p.brand, p.spec FROM product_code c LEFT JOIN product p ON p.id = c.product_id AND p.deleted = 0
c.deleted = 0 AND c.code_type = #{codeType} AND c.product_id = #{productId} AND c.batch_no LIKE CONCAT('%', #{batchNo}, '%') AND c.status = #{status}
AND ( c.code LIKE CONCAT('%', #{keyword}, '%') OR p.product_no LIKE CONCAT('%', #{keyword}, '%') OR p.product_name LIKE CONCAT('%', #{keyword}, '%') OR p.category LIKE CONCAT('%', #{keyword}, '%') OR p.brand LIKE CONCAT('%', #{keyword}, '%') OR p.spec LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY c.id DESC LIMIT #{offset}, #{size}

